"""R2V LoCoMo recompute. Protocol derived from v52_t4d_locomo_frozen_cross_benchmark.py (copied semantics)."""
import json, pickle, re, time
import numpy as np
from pathlib import Path
WORK=Path('/mnt/c/Users/MDP/dev/llmzip-work')
RAW=WORK/'drive'/'locomo10.json'; AUD=WORK/'drive'/'audit_layer'
TOPK=3; NTR=20

# ---- verbatim semantics from frozen T4D script ----
def norm_evidence(x):
    if x is None: return []
    if isinstance(x,str):
        vals=re.findall(r"D\d+:\d+",x); return vals if vals else [x]
    if isinstance(x,(list,tuple)):
        out=[]
        for z in x:
            if isinstance(z,str):
                ids=re.findall(r"D\d+:\d+",z); out.extend(ids if ids else [z])
            elif isinstance(z,dict):
                did=z.get("dia_id") or z.get("id")
                if did: out.append(str(did))
        return list(dict.fromkeys(out))
    return []
def stable_archive_seed(ci,t): return 5_100_000+ci*100_000+t*100
def hspec(seed,b=96):
    r=np.random.default_rng(seed); perm=r.permutation(96); qs=[]
    for _ in range(96//b):
        A=r.standard_normal((b,b)); Q,R=np.linalg.qr(A)
        sg=np.where(np.diag(R)<0,-1.0,1.0); qs.append(Q*sg[None,:])
    return perm,qs
def happly(X,perm,qs,b=96):
    xp=np.asarray(X,float)[...,perm]; o=np.empty_like(xp)
    for j,Q in enumerate(qs):
        sl=slice(j*b,(j+1)*b); o[...,sl]=xp[...,sl]@Q
    return o
def evidence_rows(ids,id_to_row):
    out=[]
    for x in ids:
        if x in id_to_row: out.append(int(id_to_row[x]))
    return list(dict.fromkeys(out))

t0=time.time()
raw=json.loads(RAW.read_text())
corr={}
for f in sorted(AUD.glob('errors_conv_*.json')):
    rows=json.loads(f.read_text())
    if not isinstance(rows,list): continue
    for r in rows:
        qid=r.get('question_id')
        if qid: corr[str(qid)]={'correct_evidence':norm_evidence(r.get('correct_evidence')) if 'correct_evidence' in r else None,
                                'has':('correct_evidence' in r)}
print('audit corrections:',len(corr))

# ---- verify pkl order == raw order ----
pkls=[pickle.load(open(str(WORK/'regen'/'locomo'/f'locomo_{i}.pkl'),'rb')) for i in range(10)]
assert [p['conv_id'] for p in pkls]==[f'locomo_{i}' for i in range(10)]
ok=True; nqa=0
for i,(item,p) in enumerate(zip(raw,pkls)):
    rq=[f'locomo_{i}_qa{j}' for j in range(len(item['qa']))]
    pq=[q['question_id'] for q in p['qas']]
    if rq!=pq: ok=False; print('ORDER MISMATCH conv',i)
    # raw evidence cross-check on first qa
    if norm_evidence(item['qa'][0].get('evidence'))!=norm_evidence(p['qas'][0]['raw_evidence']):
        ok=False; print('EVID MISMATCH conv',i)
    nqa+=len(pq)
print('pkl order == raw order:',ok,'total qas:',nqa)
cats=set()
for p in pkls:
    for q in p['qas']: cats.add(int(q['category']))
print('categories in pkls:',sorted(cats))

# ---- cohort gold (audit-clean) ----
def audit_gold(p,qi,q):
    qid=q['question_id']; z=corr.get(qid)
    ce=list(z['correct_evidence']) if (z and z['has']) else list(norm_evidence(q['raw_evidence']))
    return evidence_rows(ce,p['id_to_row'])
Ngold_valid=0; Ntot=0
for p in pkls:
    for qi,q in enumerate(p['qas']):
        if int(q['category']) not in (1,2,3,4): continue
        Ntot+=1
        if audit_gold(p,qi,q): Ngold_valid+=1
print('Cat1-4 q=%d audit-valid=%d'%(Ntot,Ngold_valid))

def frac_of(top,gold):
    R=set(map(int,top)); G=set(map(int,gold)); return len(R&G)/len(G)

def eval_queries(p,ci,dist2d,golds):
    """dist2d: (nq,N) hamming; returns per-q trial-mean fractional (nan if invalid)."""
    N=dist2d.shape[1]
    pri=[np.random.default_rng(stable_archive_seed(ci,t)+99).random(N) for t in range(NTR)]
    out=[]
    for qi,g in enumerate(golds):
        if not g: out.append(np.nan); continue
        d=dist2d[qi]; s=0.0
        for t in range(NTR):
            order=np.lexsort((pri[t],d)); s+=frac_of(order[:TOPK],g)
        out.append(s/NTR)
    return np.array(out)

def full_dist(C,QC):
    D=(np.asarray(C)>=0); Q=(np.asarray(QC)>=0)
    return np.count_nonzero(Q[:,None,:]!=D[None,:,:],axis=2).astype(np.int16)

# ---- GATE native ----
nat_all=[]
for ci,p in enumerate(pkls):
    C,Q=p['C'],p['QC']
    golds=[audit_gold(p,qi,q) if int(q['category']) in (1,2,3,4) else [] for qi,q in enumerate(p['qas'])]
    v=eval_queries(p,ci,full_dist(C,Q),golds)
    nat_all.append(v)
nat_all=np.concatenate(nat_all)
native=float(np.nanmean(nat_all)); nvalid=int(np.isfinite(nat_all).sum())
print('NATIVE=%.14f nvalid=%d'%(native,nvalid))

# ---- Haar full-96 ----
for s in [43001,43002,43003,43004,43005]:
    acc=[]
    for ci,p in enumerate(pkls):
        C,Q=p['C'],p['QC']
        perm,qs=hspec(s,96); Cr=happly(C,perm,qs,96); Qr=happly(Q,perm,qs,96)
        golds=[audit_gold(p,qi,q) if int(q['category']) in (1,2,3,4) else [] for qi,q in enumerate(p['qas'])]
        acc.append(eval_queries(p,ci,full_dist(Cr,Qr),golds))
    m=float(np.nanmean(np.concatenate(acc)))
    print('HAAR96 seed %d: %.14f'%(s,m))
    if s==43001: pass

# ---- budget BOT k=48 ----
acc=[]
for ci,p in enumerate(pkls):
    C,Q=np.asarray(p['C']),np.asarray(p['QC'])
    var=C.var(axis=0); bot=np.argsort(var,kind='stable')[:48]
    golds=[audit_gold(p,qi,q) if int(q['category']) in (1,2,3,4) else [] for qi,q in enumerate(p['qas'])]
    acc.append(eval_queries(p,ci,full_dist(C[:,bot],Q[:,bot]),golds))
bot48=float(np.nanmean(np.concatenate(acc)))
print('BOT_k48=%.14f gap_pp=%.4f'%(bot48,(bot48-native)*100))

# ---- block-2 ----
def anti_perm(var):
    desc=np.argsort(var,kind='stable')[::-1]; top=desc[:48]; bot=desc[::-1][:48]
    pm=np.empty(96,dtype=int); pm[0::2]=top; pm[1::2]=bot; return pm
for s in [43001,43002,43003]:
    for fam in ['RANDPAIR','MATCHED','ANTIMATCHED']:
        acc=[]
        for ci,p in enumerate(pkls):
            C,Q=np.asarray(p['C'],float),np.asarray(p['QC'],float)
            perm,qs=hspec(s,2)
            if fam=='MATCHED': perm=np.argsort(C.var(axis=0),kind='stable')[::-1]
